"""SQL generated by db/write.py, checked against TypeORM's update semantics."""

from __future__ import annotations

import pytest

from assessment_worker.db.write import column_name, insert, update


class RecordingConnection:
    def __init__(self) -> None:
        self.sql = ""
        self.arguments: tuple[object, ...] = ()

    async def execute(self, sql: str, *arguments: object) -> str:
        self.sql, self.arguments = sql, arguments
        return "UPDATE 1"

    async def fetch(self, sql: str, *arguments: object) -> list[object]:
        self.sql, self.arguments = sql, arguments
        return []


def test_column_name_maps_camel_case():
    assert column_name("currentPageIds") == "current_page_ids"
    assert column_name("processingState") == "processing_state"
    assert column_name("id") == "id"


def test_column_name_rejects_injection():
    with pytest.raises(ValueError):
        column_name("id=1;drop table x")


async def test_update_sets_columns_and_touches_updated_at():
    connection = RecordingConnection()
    await update(
        connection,
        "school_assessment_submissions",
        {"processingState": "queued"},
        {"id": "s1", "schoolId": "c1", "inputRevision": 4},
    )
    assert connection.sql.startswith(
        "UPDATE school_assessment_submissions SET processing_state=$1, "
        "updated_at=now() WHERE"
    )
    assert "id=$2 AND school_id=$3 AND input_revision=$4" in connection.sql
    assert connection.arguments == ("queued", "s1", "c1", 4)


async def test_update_can_opt_out_of_the_timestamp():
    connection = RecordingConnection()
    await update(
        connection, "school_assessment_jobs", {"state": "running"}, {"id": "j1"},
        touch=False,
    )
    assert "updated_at" not in connection.sql


async def test_update_requires_values():
    connection = RecordingConnection()
    with pytest.raises(ValueError):
        await update(connection, "t", {}, {"id": "1"})
    with pytest.raises(ValueError):
        await update(connection, "t", {"a": 1}, {})


async def test_insert_fills_timestamps_and_keeps_arguments_aligned():
    connection = RecordingConnection()
    await insert(
        connection,
        "school_assessment_pages",
        {"jobId": "j1", "sha256": None},
        touch=True,
    )
    assert connection.sql.startswith(
        "INSERT INTO school_assessment_pages (job_id, sha256, created_at, "
        "updated_at) VALUES ($1, $2, now(), now())"
    )
    # None is a real NULL and must stay in the argument list.
    assert connection.arguments == ("j1", None)
